package com.hrm.service;
import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.jdbc.support.JdbcTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import com.hrm.security.AuthenticatedAccount;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfSystemProperty(named="hrm.department.sqlserver-tests",matches="true")
class DepartmentWorkflowSqlServerTest {
 @Test void headDecisionAuditAndDuplicateProtectionRollBackTogether()throws Exception{
  var properties=new Properties();properties.load(Files.newBufferedReader(Path.of("src/main/resources/application-local.properties")));var db=new JdbcTemplate(new DriverManagerDataSource(properties.getProperty("spring.datasource.url"),properties.getProperty("spring.datasource.username"),properties.getProperty("spring.datasource.password")));
  var a=db.queryForMap("SELECT ac.account_id,ac.employee_id,r.role_code FROM dbo.accounts ac JOIN dbo.roles r ON r.role_id=ac.role_id WHERE ac.username='demo.head.tv' AND ac.is_active=1");var actor=new AuthenticatedAccount(((Number)a.get("account_id")).longValue(),((Number)a.get("employee_id")).longValue(),"demo.head.tv",a.get("role_code").toString());
  var access=new DepartmentWorkspaceAccess(db);var service=new DepartmentReviewService(db,access,new NotificationPublisher(db,false));String query="SELECT TOP(1) source.* FROM "+DepartmentReviewService.SOURCES+" WHERE source.sourceStatus IN ('CHO_DUYET','CHO_XU_LY','DANG_XU_LY') AND source.employee_id<>? AND "+access.predicate(actor,"source.employee_id","CAST(source.starts AS date)")+" AND NOT EXISTS(SELECT 1 FROM dbo.department_workflow_reviews r WHERE r.source_type=source.kind AND r.source_id=source.id AND r.source_fingerprint=source.fingerprint)";var candidates=db.queryForList(query,actor.employeeId());Assumptions.assumeFalse(candidates.isEmpty(),"No pending independent review fixture");var row=candidates.get(0);String kind=row.get("kind").toString();long id=((Number)row.get("id")).longValue();long before=db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.department_workflow_reviews",Long.class);
  new TransactionTemplate(new JdbcTransactionManager(db.getDataSource())).executeWithoutResult(tx->{try{service.decide(actor,kind,id,true,"Rollback-only integration verification",row.get("fingerprint").toString());service.requireApproval(kind,id);assertEquals(before+1,db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.department_workflow_reviews",Long.class));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.decide(actor,kind,id,true,"Duplicate",row.get("fingerprint").toString()));}finally{tx.setRollbackOnly();}});
  assertEquals(before,db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.department_workflow_reviews",Long.class));
 }
}
